// Package requestid provides an HTTP handler wrapper ("middleware") that
// stows the GitHub request ID in a Context to make it easy to plumb it through
// a service from the incoming request to an outgoing one.
//
// Request IDs generated by glb (haproxy) encode various data about the connection
// (see https://github.com/github/githubber-content/blob/master/docs/technology/dotcom/request-id.md)
// whereas request IDs generated internally, either by this package or by the monolith
// (see https://github.com/github/github/blob/master/lib/rack/request_id.rb#L57)
// are simply 128-bit random numbers in UUID format.
package requestid

import (
	"context"
	"fmt"
	"net/http"
	"os"
	"time"

	"github.com/github/github-telemetry-go/kvp"
	"github.com/github/go-http/v2/middleware/headers"
	"github.com/google/uuid"
)

// GitHubRequestIDLabel is the label used for the GitHub request ID field.
const GitHubRequestIDLabel = "request_id"

// RequestIDKey is the context key for the X-GitHub-Request-ID value.
const ctxRequestIDKey = "go-http-RequestId"

// Handler is a middleware that handles the github request id stuff.
func Handler(next http.Handler) http.Handler {
	fn := func(w http.ResponseWriter, r *http.Request) {
		id := r.Header.Get(headers.GitHubRequestID)
		if id == "" {
			id = NewGitHubRequestID()
		}

		r = r.WithContext(WithGitHubRequestID(r.Context(), id))

		next.ServeHTTP(w, r)
	}
	return http.HandlerFunc(fn)
}

// GetGitHubRequestID returns the GitHub request ID if one is present.
func GetGitHubRequestID(ctx context.Context) string {
	if ctx == nil {
		return ""
	}
	if reqID, ok := ctx.Value(ctxRequestIDKey).(string); ok {
		return reqID
	}
	return ""
}

// GetGitHubRequestIDField returns a kvp field intended for consistent GitHub request ID logging.
func GetGitHubRequestIDField(ctx context.Context) kvp.Field {
	requestID := GetGitHubRequestID(ctx)
	if requestID == "" {
		requestID = "unknown"
	}

	return kvp.String(GitHubRequestIDLabel, requestID)
}

// WithGitHubRequestID creates a new context based on the supplied parent, with the GitHubRequestId
// set to the specified value. If a GitHubRequestID already exists, it will be overwritten.
func WithGitHubRequestID(ctx context.Context, id string) context.Context {
	//nolint:staticcheck,revive // SA1029 should be ignored, context collisions are acceptable across major versions
	return context.WithValue(ctx, ctxRequestIDKey, id)
}

// NewGitHubRequestID generates a new request id. Note that there is no need to call this yourself
// if you are using the middleware handler, since the middleware handler will call this itself to
// insert a new request id into the context if one is not found in the request headers.
func NewGitHubRequestID() string {
	return uuid.New().String()
}

// WithNewGitHubRequestID generates a new request id and adds it to the context. It is the caller's
// responsibility to ensure that there is not already a request id present in the context.
func WithNewGitHubRequestID(ctx context.Context) context.Context {
	//nolint:staticcheck,revive // SA1029 should be ignored, context collisions are acceptable across major versions
	return context.WithValue(ctx, ctxRequestIDKey, NewGitHubRequestID())
}

// Forward is a request hook that looks for X-GitHub-Request-Id in the incoming context and adds them to r's headers.
func Forward(r *http.Request) {
	ctx := r.Context()

	if reqID := GetGitHubRequestID(ctx); reqID != "" {
		r.Header.Set(headers.GitHubRequestID, reqID)
	}

	// If going to a GitHub domain, the X-GLB-Via header is also required (or GLB will strip X-GitHub-Request-Id)
	if host, err := os.Hostname(); err == nil {
		r.Header.Set(headers.GLBVia, fmt.Sprintf("hostname=%s t=%d", host, time.Now().Unix()))
	}
}
